        // ─── Handle conversion (every RHI handle is `{ u64 value; }`) ────────────────
        template <class RhiHandle, class OurHandle>
        RhiHandle to_rhi_handle(OurHandle h) noexcept {
            RhiHandle r{};
            r.value = h.value;
            return r;
        }
        template <class OurHandle, class RhiHandle>
        OurHandle from_rhi_handle(RhiHandle h) noexcept {
            OurHandle o{};
            o.value = h.value;
            return o;
        }

        // ─── Status / error conversion ────────────────────────────────────────────
        RhiErrorCode map_error_code(R::RhiErrorCode code) noexcept {
            switch (code) {
            case R::RhiErrorCode::Unsupported: return RhiErrorCode::Unsupported;
            case R::RhiErrorCode::OperationFailed: return RhiErrorCode::OperationFailed;
            case R::RhiErrorCode::OutOfMemory: return RhiErrorCode::OutOfMemory;
            case R::RhiErrorCode::DeviceLost: return RhiErrorCode::DeviceLost;
            case R::RhiErrorCode::SurfaceLost: return RhiErrorCode::SurfaceLost;
            case R::RhiErrorCode::FullScreenExclusiveLost: return RhiErrorCode::FullScreenExclusiveLost;
            case R::RhiErrorCode::NotReady: return RhiErrorCode::NotReady;
            case R::RhiErrorCode::InvalidArgument: return RhiErrorCode::InvalidArgument;
            }
            return RhiErrorCode::OperationFailed;
        }

        void set_ok(RhiStatus &status) {
            status.ok = true;
            status.code = RhiErrorCode::OperationFailed;
            status.message = rust::String();
        }

        void set_error(RhiStatus &status, const R::RhiError &error) {
            status.ok = false;
            status.code = map_error_code(error.code);
            status.message = rust::String::lossy(error.message);
        }

        template <class OurValue, class RhiValue>
        OurValue unwrap(R::RhiExpected<RhiValue> result, RhiStatus &status, OurValue on_error = OurValue{}) {
            if (!result) {
                set_error(status, result.error());
                return on_error;
            }
            set_ok(status);
            return OurValue{*result};
        }

        template <class OurHandle, class RhiHandle>
        OurHandle unwrap_handle(R::RhiExpected<RhiHandle> result, RhiStatus &status) {
            if (!result) {
                set_error(status, result.error());
                return OurHandle{};
            }
            set_ok(status);
            return from_rhi_handle<OurHandle>(*result);
        }

        void unwrap_void(R::RhiResult result, RhiStatus &status) {
            if (!result) {
                set_error(status, result.error());
                return;
            }
            set_ok(status);
        }

