        // ─── Descriptor conversions ───────────────────────────────────────────────
        R::ShaderEntry to_rhi(const ShaderEntry &e, std::string &entry_point_storage) {
            entry_point_storage = std::string(e.entry_point);
            R::ShaderEntry out{};
            out.module = to_rhi_handle<R::ShaderModuleHandle>(e.module);
            out.entry_point = entry_point_storage.c_str();
            out.stage = static_cast<R::ShaderStage>(e.stage);
            return out;
        }

        R::VertexAttribute to_rhi(const VertexAttribute &a, std::string &semantic_storage) {
            semantic_storage = std::string(a.semantic_name);
            R::VertexAttribute out{};
            out.format = map(a.format);
            out.offset = a.offset;
            out.shader_location = a.shader_location;
            out.semantic_name = semantic_storage.c_str();
            out.semantic_index = a.semantic_index;
            return out;
        }

        R::BindGroupLayoutEntry to_rhi(const BindGroupLayoutEntry &e) {
            R::BindGroupLayoutEntry out{};
            out.binding = e.binding;
            out.shader_register = e.shader_register;
            out.type = map(e.kind);
            out.visibility = static_cast<R::ShaderStage>(e.visibility);
            out.count = e.count;
            out.has_dynamic_offset = e.has_dynamic_offset;
            out.flags = static_cast<R::BindingFlags>(e.flags);
            out.storage_format = map(e.storage_format);
            out.storage_access = map(e.storage_access);
            out.sampler_is_comparison = e.sampler_is_comparison;
            out.sampled_texture_is_depth = e.sampled_texture_is_depth;
            out.sampled_texture_is_multisampled = e.sampled_texture_is_multisampled;
            return out;
        }

        R::BindGroupEntry to_rhi(const BindGroupEntry &e) {
            R::BindGroupEntry out{};
            out.binding = e.binding;
            out.array_element = e.array_element;
            out.buffer = to_rhi_handle<R::BufferHandle>(e.buffer);
            out.offset = e.offset;
            out.size = e.size;
            out.structure_stride = e.structure_stride;
            out.texture_view = to_rhi_handle<R::TextureViewHandle>(e.texture_view);
            out.sampler = to_rhi_handle<R::SamplerHandle>(e.sampler);
            out.acceleration_structure = to_rhi_handle<R::AccelerationStructureHandle>(e.acceleration_structure);
            return out;
        }

        R::PushConstantRange to_rhi(const PushConstantRange &p) {
            R::PushConstantRange out{};
            out.stages = static_cast<R::ShaderStage>(p.stages);
            out.offset = p.offset;
            out.size = p.size;
            out.shader_register = p.shader_register;
            out.register_space = p.register_space;
            return out;
        }

