            R::AccelerationStructureTrianglesDesc out{};
            out.vertex_buffer = to_rhi_handle<R::BufferHandle>(t.vertex_buffer);
            out.vertex_offset = t.vertex_offset;
            out.vertex_format = map(t.vertex_format);
            out.vertex_stride = t.vertex_stride;
            out.max_vertex = t.max_vertex;
            out.index_buffer = to_rhi_handle<R::BufferHandle>(t.index_buffer);
            out.index_offset = t.index_offset;
            out.index_format = map(t.index_format);
            out.transform_buffer = to_rhi_handle<R::BufferHandle>(t.transform_buffer);
            out.transform_offset = t.transform_offset;
            out.opacity_micromap = to_rhi_handle<R::OpacityMicromapHandle>(t.opacity_micromap);
            out.opacity_micromap_index_buffer = to_rhi_handle<R::BufferHandle>(t.opacity_micromap_index_buffer);
