        out.max_color_attachments = limits.max_color_attachments;
        out.max_framebuffer_sample_count = limits.max_framebuffer_sample_count;
        out.framebuffer_sample_counts = limits.framebuffer_sample_counts;
        out.supports_minimum_depth_resolve = limits.supports_minimum_depth_resolve;
        out.supports_bc_texture_compression = limits.supports_bc_texture_compression;
        out.max_compute_workgroup_size_x = limits.max_compute_workgroup_size_x;
