    namespace {
        rust::String feature_string(R::Feature feature) {
            const char *name = R::feature_name(feature);
            return rust::String::lossy(name != nullptr ? name : "");
        }

        rust::String view_string(std::string_view text) {
            return rust::String::lossy(text.data(), text.size());
        }

        QueueClass from_engine(R::QueueClass v) noexcept {
            switch (v) {
            case R::QueueClass::Graphics: return QueueClass::Graphics;
            case R::QueueClass::Compute: return QueueClass::Compute;
            case R::QueueClass::Transfer: return QueueClass::Transfer;
            case R::QueueClass::Sparse: return QueueClass::Sparse;
            case R::QueueClass::VideoDecode: return QueueClass::VideoDecode;
            case R::QueueClass::VideoEncode: return QueueClass::VideoEncode;
            }
            return QueueClass::Graphics;
        }
    } // namespace

    rust::Vec<rust::String> rhi_enabled_features(const RhiDevice &device) {
        rust::Vec<rust::String> out;
        device.enabled_features().for_each([&](R::Feature feature) { out.push_back(feature_string(feature)); });
        return out;
    }

    rust::Vec<rust::String> rhi_all_feature_names() {
        rust::Vec<rust::String> out;
        for (std::size_t i = 0; i < R::feature_count; ++i) {
            out.push_back(feature_string(static_cast<R::Feature>(i)));
        }
        return out;
    }

    rust::Vec<ExtensionInfo> rhi_enabled_extensions(const RhiDevice &device) {
        rust::Vec<ExtensionInfo> out;
        for (const R::ExtensionId &extension : device.enabled_extensions()) {
            ExtensionInfo info{};
            info.name_space = view_string(extension.name_space);
            info.name = view_string(extension.name);
            info.version = extension.version;
            out.push_back(std::move(info));
        }
        return out;
    }

    rust::Vec<QueueInfo> rhi_queue_infos(const RhiDevice &device) {
        rust::Vec<QueueInfo> out;
        for (const R::QueueInfo &queue : device.queue_infos()) {
            QueueInfo info{};
            info.queue = from_engine(queue.queue);
            info.capabilities = static_cast<std::uint32_t>(queue.capabilities);
            info.lane_count = queue.lane_count;
            info.physical_group = queue.physical_group;
            info.likely_parallel_with_graphics = queue.likely_parallel_with_graphics;
            info.dedicated = queue.dedicated;
            info.label = rust::String::lossy(queue.label != nullptr ? queue.label : "");
            out.push_back(std::move(info));
        }
        return out;
    }

