    // ─── Pipelines ────────────────────────────────────────────────────────────────

    RenderPipelineHandle rhi_create_render_pipeline(RhiDevice &device, const RenderPipelineDesc &desc, RhiStatus &status) {
        const std::string label(desc.label);
        std::string vertex_entry, fragment_entry;
        R::RenderPipelineDesc d{};
        d.layout = to_rhi_handle<R::PipelineLayoutHandle>(desc.layout);
        d.vertex = to_rhi(desc.vertex, vertex_entry);
        d.fragment = to_rhi(desc.fragment, fragment_entry);

        // Keep per-attribute semantic-name storage and the vertex-buffer vector alive for the call.
        std::vector<std::vector<std::string>> semantic_storage(desc.vertex_buffers.size());
        std::vector<std::vector<R::VertexAttribute>> attribute_storage(desc.vertex_buffers.size());
        std::vector<R::VertexBufferLayout> vertex_buffers;
        vertex_buffers.reserve(desc.vertex_buffers.size());
        for (std::size_t i = 0; i < desc.vertex_buffers.size(); ++i) {
            const auto &vb = desc.vertex_buffers[i];
            semantic_storage[i].resize(vb.attributes.size());
            attribute_storage[i].reserve(vb.attributes.size());
            for (std::size_t a = 0; a < vb.attributes.size(); ++a) {
                attribute_storage[i].push_back(to_rhi(vb.attributes[a], semantic_storage[i][a]));
            }
            R::VertexBufferLayout layout{};
            layout.stride = vb.stride;
            layout.step_mode = map(vb.step_mode);
            layout.attributes = attribute_storage[i];
            vertex_buffers.push_back(layout);
        }
        d.vertex_buffers = vertex_buffers;

        d.topology = map(desc.topology);
        d.rasterization.polygon_mode = map(desc.rasterization.polygon_mode);
        d.rasterization.cull_mode = map(desc.rasterization.cull_mode);
        d.rasterization.front_face = map(desc.rasterization.front_face);
        d.rasterization.depth_bias_constant = desc.rasterization.depth_bias_constant;
        d.rasterization.depth_bias_slope_scale = desc.rasterization.depth_bias_slope_scale;
        d.rasterization.depth_bias_clamp = desc.rasterization.depth_bias_clamp;
        d.rasterization.line_width = desc.rasterization.line_width;

        d.multisample.samples = map(desc.multisample.samples);
        d.multisample.sample_mask = desc.multisample.sample_mask;
        d.multisample.alpha_to_coverage_enable = desc.multisample.alpha_to_coverage_enable;
        d.multisample.sample_locations_enable = desc.multisample.sample_locations_enable;

        d.depth_stencil.format = map(desc.depth_stencil.format);
        d.depth_stencil.depth_test_enable = desc.depth_stencil.depth_test_enable;
        d.depth_stencil.depth_write_enable = desc.depth_stencil.depth_write_enable;
        d.depth_stencil.depth_compare = map(desc.depth_stencil.depth_compare);
        d.depth_stencil.stencil_test_enable = desc.depth_stencil.stencil_test_enable;
        d.depth_stencil.stencil_front = map(desc.depth_stencil.stencil_front);
        d.depth_stencil.stencil_back = map(desc.depth_stencil.stencil_back);
        d.depth_stencil.stencil_read_mask = desc.depth_stencil.stencil_read_mask;
        d.depth_stencil.stencil_write_mask = desc.depth_stencil.stencil_write_mask;
        d.depth_stencil.depth_bounds_test_enable = desc.depth_stencil.depth_bounds_test_enable;

        std::vector<R::ColorTargetState> color_targets;
        color_targets.reserve(desc.color_targets.size());
        for (const auto &c : desc.color_targets) {
            R::ColorTargetState t{};
            t.format = map(c.format);
            t.blend_enable = c.blend_enable;
            t.color.src_factor = map(c.color.src_factor);
            t.color.dst_factor = map(c.color.dst_factor);
            t.color.op = map(c.color.op);
            t.alpha.src_factor = map(c.alpha.src_factor);
            t.alpha.dst_factor = map(c.alpha.dst_factor);
            t.alpha.op = map(c.alpha.op);
            t.write_mask = static_cast<R::ColorWriteMask>(c.write_mask);
            color_targets.push_back(t);
        }
        d.color_targets = color_targets;
        d.label = label.c_str();

        return unwrap_handle<RenderPipelineHandle>(device.create_render_pipeline(d), status);
    }

