    RayTracingPipelineHandle rhi_create_ray_tracing_pipeline(
        RhiDevice &device, const RayTracingPipelineDesc &desc, RhiStatus &status) {
        const std::string label(desc.label);
        // Keep every ShaderEntry's entry_point string alive for the call.
        std::vector<std::array<std::string, 4>> entry_storage(desc.groups.size());
        std::vector<R::RayTracingShaderGroupDesc> groups;
        groups.reserve(desc.groups.size());
        for (std::size_t i = 0; i < desc.groups.size(); ++i) {
            const auto &g = desc.groups[i];
            R::RayTracingShaderGroupDesc out{};
            out.type = map(g.group_type);
            out.general = to_rhi(g.general, entry_storage[i][0]);
            out.closest_hit = to_rhi(g.closest_hit, entry_storage[i][1]);
            out.any_hit = to_rhi(g.any_hit, entry_storage[i][2]);
            out.intersection = to_rhi(g.intersection, entry_storage[i][3]);
            groups.push_back(out);
        }
        R::RayTracingPipelineDesc d{};
        d.layout = to_rhi_handle<R::PipelineLayoutHandle>(desc.layout);
        d.groups = groups;
        d.max_ray_recursion_depth = desc.max_ray_recursion_depth;
        d.label = label.c_str();
        return unwrap_handle<RayTracingPipelineHandle>(device.create_ray_tracing_pipeline(d), status);
    }

