    rust::Vec<std::uint8_t> rhi_pack_acceleration_structure_instances(
        rust::Slice<const AccelerationStructureInstance> instances) {
        static_assert(sizeof(R::AccelerationStructureInstance) == 64);
        rust::Vec<std::uint8_t> out;
        out.reserve(instances.size() * sizeof(R::AccelerationStructureInstance));
        for (const auto &src : instances) {
            R::AccelerationStructureInstance packed{};
            for (int i = 0; i < 12; ++i) {
                packed.transform[static_cast<std::size_t>(i)] = src.transform[static_cast<std::size_t>(i)];
            }
            packed.set_custom_index_and_mask(src.custom_index, src.mask);
            packed.set_shader_binding_table_offset_and_flags(src.shader_binding_table_offset, src.flags);
            packed.acceleration_structure_device_address = src.blas_device_address;

            std::array<std::uint8_t, sizeof(R::AccelerationStructureInstance)> bytes{};
            std::memcpy(bytes.data(), &packed, sizeof(packed));
            for (auto b : bytes) {
                out.push_back(b);
            }
        }
        return out;
    }

