    void rhi_submit_with(RhiDevice &device, const SubmitDesc &desc, RhiStatus &status) {
        const std::string label(desc.label);
        std::vector<R::CommandBufferHandle> buffers;
        buffers.reserve(desc.command_buffers.size());
        for (const auto &b : desc.command_buffers) {
            buffers.push_back(to_rhi_handle<R::CommandBufferHandle>(b));
        }
        std::vector<R::QueueSemaphoreWait> waits;
        waits.reserve(desc.waits.size());
        for (const auto &w : desc.waits) {
            waits.push_back(R::QueueSemaphoreWait{to_rhi_handle<R::SemaphoreHandle>(w.semaphore), w.value,
                                                  static_cast<R::PipelineStage>(w.stages)});
        }
        std::vector<R::QueueSemaphoreSignal> signals;
        signals.reserve(desc.signals.size());
        for (const auto &s : desc.signals) {
            signals.push_back(R::QueueSemaphoreSignal{to_rhi_handle<R::SemaphoreHandle>(s.semaphore), s.value,
                                                      static_cast<R::PipelineStage>(s.stages)});
        }
        R::SubmitDesc d{};
        d.queue = map(desc.queue);
        d.command_buffers = buffers;
        d.waits = waits;
        d.signals = signals;
        d.fence = to_rhi_handle<R::FenceHandle>(desc.fence);
        d.flags = desc.one_shot ? R::SubmitFlags::OneShot : R::SubmitFlags::None;
        d.label = label.c_str();
        unwrap_void(device.submit(d), status);
    }

