    std::unique_ptr<RenderPassEncoder> ce_begin_render_pass(CommandEncoder &encoder, const RenderPassDesc &desc, RhiStatus &status) {
        const std::string label(desc.label);
        std::vector<R::ColorAttachment> color_attachments;
        color_attachments.reserve(desc.color_attachments.size());
        for (const auto &c : desc.color_attachments) {
            R::ColorAttachment out{};
            out.view = to_rhi_handle<R::TextureViewHandle>(c.view);
            out.resolve_view = to_rhi_handle<R::TextureViewHandle>(c.resolve_view);
            out.load_op = map(c.load_op);
            out.store_op = map(c.store_op);
            out.clear_color = {c.clear_color.r, c.clear_color.g, c.clear_color.b, c.clear_color.a};
            color_attachments.push_back(out);
        }
        R::RenderPassDesc d{};
        d.color_attachments = color_attachments;
        if (desc.has_depth_stencil) {
            R::DepthStencilAttachment ds{};
            ds.view = to_rhi_handle<R::TextureViewHandle>(desc.depth_stencil.view);
            ds.depth_load_op = map(desc.depth_stencil.depth_load_op);
            ds.depth_store_op = map(desc.depth_stencil.depth_store_op);
            ds.stencil_load_op = map(desc.depth_stencil.stencil_load_op);
            ds.stencil_store_op = map(desc.depth_stencil.stencil_store_op);
            ds.clear_value = {desc.depth_stencil.clear_depth, desc.depth_stencil.clear_stencil};
            d.depth_stencil = ds;
        }
        d.render_area = {desc.render_area.x, desc.render_area.y, desc.render_area.width, desc.render_area.height};
        d.label = label.c_str();

        auto result = encoder.begin_render_pass(d);
        if (!result) {
            set_error(status, result.error());
            return nullptr;
        }
        set_ok(status);
        return std::move(*result);
    }

