    void ce_barrier(CommandEncoder &encoder,
                    rust::Slice<const GlobalBarrier> global_barriers,
                    rust::Slice<const BufferBarrier> buffer_barriers,
                    rust::Slice<const TextureBarrier> texture_barriers) noexcept {
        std::vector<R::GlobalBarrier> globals;
        globals.reserve(global_barriers.size());
        for (const auto &b : global_barriers) {
            globals.push_back(R::GlobalBarrier{
                static_cast<R::PipelineStage>(b.src_stage), static_cast<R::AccessFlags>(b.src_access),
                static_cast<R::PipelineStage>(b.dst_stage), static_cast<R::AccessFlags>(b.dst_access)});
        }
        std::vector<R::BufferBarrier> buffers;
        buffers.reserve(buffer_barriers.size());
        for (const auto &b : buffer_barriers) {
            R::BufferBarrier out{};
            out.buffer = to_rhi_handle<R::BufferHandle>(b.buffer);
            out.src_stage = static_cast<R::PipelineStage>(b.src_stage);
            out.src_access = static_cast<R::AccessFlags>(b.src_access);
            out.dst_stage = static_cast<R::PipelineStage>(b.dst_stage);
            out.dst_access = static_cast<R::AccessFlags>(b.dst_access);
            out.ownership = map(b.ownership);
            out.offset = b.offset;
            out.size = b.size;
            buffers.push_back(out);
        }
        std::vector<R::TextureBarrier> textures;
        textures.reserve(texture_barriers.size());
        for (const auto &b : texture_barriers) {
            R::TextureBarrier out{};
            out.texture = to_rhi_handle<R::TextureHandle>(b.texture);
            out.src_stage = static_cast<R::PipelineStage>(b.src_stage);
            out.src_access = static_cast<R::AccessFlags>(b.src_access);
            out.dst_stage = static_cast<R::PipelineStage>(b.dst_stage);
            out.dst_access = static_cast<R::AccessFlags>(b.dst_access);
            out.ownership = map(b.ownership);
            out.old_layout = map(b.old_layout);
            out.new_layout = map(b.new_layout);
            out.range = {b.range.base_mip_level, b.range.mip_level_count, b.range.base_array_layer, b.range.array_layer_count};
            textures.push_back(out);
        }
        encoder.barrier(globals, buffers, textures);
    }

