    void ce_blit_texture(CommandEncoder &encoder, TextureHandle src, TextureHandle dst, const TextureBlit &region,
                         Filter filter) noexcept {
        R::TextureBlit r{};
        r.src_subresource = {region.src_subresource.mip_level, region.src_subresource.base_array_layer,
                             region.src_subresource.array_layer_count};
        r.src_min = {region.src_min_x, region.src_min_y, region.src_min_z};
        r.src_max = {region.src_max_x, region.src_max_y, region.src_max_z};
        r.dst_subresource = {region.dst_subresource.mip_level, region.dst_subresource.base_array_layer,
                             region.dst_subresource.array_layer_count};
        r.dst_min = {region.dst_min_x, region.dst_min_y, region.dst_min_z};
        r.dst_max = {region.dst_max_x, region.dst_max_y, region.dst_max_z};
        encoder.blit_texture(to_rhi_handle<R::TextureHandle>(src), to_rhi_handle<R::TextureHandle>(dst), r, map(filter));
    }

    void ce_clear_color_texture(CommandEncoder &encoder, TextureHandle texture, const ClearColor &color,
                                const TextureSubresourceRange &range) noexcept {
        R::ClearColor c{color.r, color.g, color.b, color.a};
        R::TextureSubresourceRange r{range.base_mip_level, range.mip_level_count, range.base_array_layer,
                                     range.array_layer_count};
        encoder.clear_color_texture(to_rhi_handle<R::TextureHandle>(texture), c, r);
    }

    void ce_clear_depth_stencil_texture(CommandEncoder &encoder, TextureHandle texture,
                                        const ClearDepthStencilValue &value,
                                        const TextureSubresourceRange &range) noexcept {
        R::ClearDepthStencil v{value.depth, value.stencil};
        R::TextureSubresourceRange r{range.base_mip_level, range.mip_level_count, range.base_array_layer,
                                     range.array_layer_count};
        encoder.clear_depth_stencil_texture(to_rhi_handle<R::TextureHandle>(texture), v, r);
    }

    void ce_build_acceleration_structures(CommandEncoder &encoder, rust::Slice<const AccelerationStructureBuildDesc> builds) {
        // Each build owns its own geometry/range storage until the call returns.
        std::vector<std::vector<R::AccelerationStructureGeometryDesc>> geometries(builds.size());
        std::vector<std::vector<R::AccelerationStructureBuildRangeInfo>> ranges(builds.size());
        std::vector<R::AccelerationStructureBuildDesc> converted;
        converted.reserve(builds.size());
        for (std::size_t i = 0; i < builds.size(); ++i) {
            converted.push_back(to_rhi(builds[i], geometries[i], ranges[i]));
        }
        encoder.build_acceleration_structures(converted);
    }

    void ce_build_opacity_micromaps(CommandEncoder &encoder, rust::Slice<const OpacityMicromapBuildDesc> builds) {
        std::vector<std::vector<R::OpacityMicromapUsageCount>> counts(builds.size());
        std::vector<R::OpacityMicromapBuildDesc> converted;
        converted.reserve(builds.size());
        for (std::size_t i = 0; i < builds.size(); ++i) {
            const auto &b = builds[i];
            counts[i] = to_rhi(b.usage_counts);
            R::OpacityMicromapBuildDesc d{};
            d.dst = to_rhi_handle<R::OpacityMicromapHandle>(b.dst);
            d.scratch_buffer = to_rhi_handle<R::BufferHandle>(b.scratch_buffer);
            d.scratch_offset = b.scratch_offset;
            d.data_buffer = to_rhi_handle<R::BufferHandle>(b.data_buffer);
            d.data_buffer_offset = b.data_buffer_offset;
            d.usage_counts = counts[i];
            converted.push_back(d);
        }
        encoder.build_opacity_micromaps(converted);
    }

    void ce_copy_acceleration_structure(CommandEncoder &encoder, AccelerationStructureHandle src,
                                        AccelerationStructureHandle dst, AccelerationStructureCopyMode mode) noexcept {
        R::AccelerationStructureCopyDesc copy{};
        copy.src = to_rhi_handle<R::AccelerationStructureHandle>(src);
        copy.dst = to_rhi_handle<R::AccelerationStructureHandle>(dst);
        copy.mode = map(mode);
        encoder.copy_acceleration_structure(copy);
    }

    void ce_set_ray_tracing_pipeline(CommandEncoder &encoder, RayTracingPipelineHandle pipeline) noexcept {
        encoder.set_ray_tracing_pipeline(to_rhi_handle<R::RayTracingPipelineHandle>(pipeline));
    }

    void ce_trace_rays(CommandEncoder &encoder, const TraceRaysDesc &desc) noexcept {
        auto region = [](const ShaderBindingTableRegion &r) {
            return R::ShaderBindingTableRegion{to_rhi_handle<R::BufferHandle>(r.buffer), r.offset, r.size, r.stride};
        };
        R::TraceRaysDesc d{};
        d.raygen = region(desc.raygen);
        d.miss = region(desc.miss);
        d.hit = region(desc.hit);
        d.callable = region(desc.callable);
        d.width = desc.width;
        d.height = desc.height;
        d.depth = desc.depth;
        encoder.trace_rays(d);
    }

